<?php require_once __DIR__.'/includes/functions.php';if(current_admin())go('index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$login=trim($_POST['login']??'');$pass=(string)($_POST['password']??'');$s=db()->prepare('SELECT * FROM users WHERE (username=? OR email=?) AND is_admin=1 LIMIT 1');$s->execute([$login,$login]);$u=$s->fetch();if($u&&$u['status']==='ACTIVE'&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$u['id'];log_activity('Admin login',(int)$u['id']);go('index.php');}$error='Invalid administrator credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ERAN+ Admin Login</title><link rel="stylesheet" href="assets/css/admin.css"></head><body class="login-page"><section class="login-card"><div class="login-brand"><span class="brand-mark">ER</span> ERAN+ Admin</div><h1>Secure admin login</h1><p>Independent management panel for ERAN+ public data and simulated requests.</p><?php if($error):?><div class="flash flash-error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>USERNAME OR EMAIL</label><input class="input" name="login" required></div><div class="field"><label>PASSWORD</label><input class="input" type="password" name="password" required></div><button class="button button-primary" type="submit">SIGN IN</button></form></section></body></html>
